// GET all tasks
app.get('/tasks', async (req, res) => {
  try {
    const tasks = await Task.find().sort({orderId:-1});
    res.json(tasks); 
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/tasks/:userId', async (req, res) => {
  try {
    const tasks = await Task.find({userId:req.params.userId}).sort({orderId:-1});
    res.json(tasks); 
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/tasks/:id/:userId', async (req, res) => {
  try {
    const tasks = await Task.findById(req.params.id);

    res.json(tasks); 
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST a new task
app.post('/tasks/:userId', async (req, res) => {
  try {
    const task = await Task.create({
      dateCreated:req.body.dateCreated,
      task: req.body.task, 
      status:false,
      orderId:req.body.orderId,
      userId:req.params.userId
    });
   // Task.create(task);
    res.status(201).json(task);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.put('/tasks/order/update/:userId',async(req,res)=>{
  try {
    const {id1,id2}=req.body.ids;
    const task1=await Task.findById(id1);
    const task2=await Task.findById(id2);
    const tempId=task1.orderId;
    task1.orderId=task2.orderId;
    task2.orderId=tempId;
    await task1.save();
    await task2.save();
    res.json({task1,task2});
  } catch (err) {
    res.status(500);
  }
   
})

// PUT update task title
app.put('/tasks/:id/:userId', async (req, res) => {
  try {
    const updatedTask = await Task.findByIdAndUpdate(
      req.params._id, 
      { task: req.body.title }, 
      { new: true }
    );
    res.json(updatedTask);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT toggle status
app.put('/tasks/status/:userId/:id', async (req, res) => {
  try {
    const task = await Task.findById(req.params.id);
    task.status = !task.status; 
    await task.save();
    res.json(task);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// DELETE a task
app.delete('/tasks/:userId/:id', async (req, res) => {
  try {
    await Task.findByIdAndDelete(req.params.id);
    res.send("deleted");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Running on port ${PORT}`); // Fixed template literal string interpolation
});
